{
  // This box: (payout box)
  //
  // TOKENS
  //   tokens(0): Payout NFT
  //
  // REGISTERS
  //   R4: (Int) height when last payment was done. Non-nullable, so set to 0 initially
  //
  // TRANSACTIONS
  // [1] Payout
  //   Input    |  Output   |   Data-Input
  // -------------------------------------
  // 0 Payout   |  Payout   |   Oracle
  // 1 Bank     |  Bank     |
  // 2 BuyBack  |  BuyBack  |

  // In the above transaction, the "payouts" (rewards) will be stored in a "Reward" box
  // The payout box just enforces the correct logic for such rewards and does not store the actual rewards

  val payoutThreshold = 100000000000000L // nanoErgs (100000 Ergs)

  val oracleNFT = fromBase64("0101010101010101010101010101010101010101010101010101010101010101") // to identify oracle pool box
  val lpNFT = fromBase64("0202020202020202020202020202020202020202020202020202020202020202")
  val buybackNft = fromBase64("0303030303030303030303030303030303030303030303030303030303030303")

  // inputs indices
  val bankInIndex = 1
  val buybackInIndex = 2

  // outputs indices
  val selfOutIndex = 0
  val bankOutIndex = 1
  val buybackOutIndex = 2

  // data inputs indices
  val oracleIndex = 0
  val lpIndex = 1

  val bankBoxIn = INPUTS(bankInIndex)
  val buybackBoxIn = INPUTS(buybackInIndex)

  val bankBoxOut = OUTPUTS(bankOutIndex)
  val successor = OUTPUTS(selfOutIndex)
  val buybackBoxOut = OUTPUTS(buybackOutIndex)

  val oracleBox = CONTEXT.dataInputs(oracleIndex)

  val validOracle = oracleBox.tokens(0)._1 == oracleNFT

  val bankDexy = bankBoxIn.tokens(1)._2

  // oracle delivers nanoErgs per 1 kg of gold
  // we divide it by 1000000 to get nanoErg per dexy, i.e. 1mg of gold
  // can assume always > 0 (ref oracle pool contracts) NanoErgs per USD
  val oracleRate = oracleBox.R4[Long].get / 1000000L

  val dexyInCirculation = $initialDexyTokens - bankDexy
  val collateralized = oracleRate * dexyInCirculation * 8 < bankBoxIn.value // > 800% collateralization

  val maxPaymentAmount = bankBoxIn.value / 200 // 0.5 % max can be taken
  val paymentAmount = bankBoxIn.value - bankBoxOut.value
  val properPayment = (paymentAmount > 0) && (paymentAmount <= maxPaymentAmount) &&
                        (buybackBoxOut.value - buybackBoxIn.value == paymentAmount)

  val lastPayment = SELF.R4[Int].get
  val buffer = 5 // error margin in height
  val delayInPayments = 5040 // ~ 1 week
  val properHeight = lastPayment + delayInPayments <= HEIGHT
  val properNewR4 = successor.R4[Int].get >= HEIGHT - buffer

  // no need to validate bank NFT and proposition here
  // value is checked in validPayout
  val validBank = bankBoxOut.tokens == bankBoxIn.tokens                     // tokens preserved

  // payout script box preservation
  val validSuccessor = successor.propositionBytes == SELF.propositionBytes && // script preserved
                       successor.tokens == SELF.tokens                     && // NFT preserved
                       successor.value >= SELF.value                       && // Ergs preserved or increased
                       properNewR4

  val validBuyBackIn = buybackBoxIn.tokens(0)._1 == buybackNft

  val validPayout = validBuyBackIn                                                && // script of reward box is correct
                    collateralized                                                && // enough over-collateralization
                    properPayment                                                 && // bank paying 0.5% of its reserves out
                    properHeight                                                     // after enough delay

  sigmaProp(validBank && validSuccessor && validPayout && validOracle)
}

{
    // LP subcontract for deposit (aka LP tokens mint) action.
    //
    // This box: (LP Mint box)
    //
    // TOKENS
    //   Tokens(0): NFT to uniquely identify this box

    val lpBoxInIndex = 0
    val lpBoxOutIndex = 0

    val selfOutIndex = 1
    val successor = OUTPUTS(selfOutIndex)

    val lpBoxIn = INPUTS(lpBoxInIndex)
    val lpBoxOut = OUTPUTS(lpBoxOutIndex)

    val lpReservesIn = lpBoxIn.tokens(1)
    val lpReservesOut = lpBoxOut.tokens(1)

    val reservesXIn = lpBoxIn.value
    val reservesYIn = lpBoxIn.tokens(2)._2

    val reservesXOut = lpBoxOut.value
    val reservesYOut = lpBoxOut.tokens(2)._2

    val supplyLpIn = $initialLp - lpReservesIn._2

    // Note:
    //    supplyLpIn = initialLp - lpReservesIn._2
    //    supplyLpOut = initialLp - lpReservesOut._2
    // Thus:
    //    deltaSupplyLp = supplyLpOut - supplyLpIn
    //                  = (initialLp - lpReservesOut._2) - (initialLp - lpReservesIn._2)
    //                  = lpReservesIn._2 - lpReservesOut._2

    val deltaSupplyLp  = lpReservesIn._2 - lpReservesOut._2
    val deltaReservesX = reservesXOut - reservesXIn
    val deltaReservesY = reservesYOut - reservesYIn

    // LP formulae below using UniSwap v2 (with initial token burning by bootstrapping with positive R4)
    val validMintLp = deltaSupplyLp > 0 && deltaReservesX > 0 && deltaReservesY > 0 && {
        val sharesUnlocked = min(
            deltaReservesX.toBigInt * supplyLpIn / reservesXIn,
            deltaReservesY.toBigInt * supplyLpIn / reservesYIn
        )
        deltaSupplyLp <= sharesUnlocked
    }

    val selfPreserved = successor.propositionBytes == SELF.propositionBytes  &&
                        successor.value >= SELF.value                        &&
                        successor.tokens == SELF.tokens

    sigmaProp(validMintLp && selfPreserved)
}

{

    // ===== Contract Information ===== //
    // Name: Phoenix HodlERG Bank
    // Description: Contract for the bank box of the hodlERG protocol.
    // Version: 1.0.0
    // Author: Luca D'Angelo (ldgaetano@protonmail.com), MGPai

    // ===== Box Contents ===== //
    // Tokens
    // 1. (BankSingletonId, 1)
    // 2. (HodlERGTokenId, HodlERGTokenAmount)
    // Registers
    // R4: Long             TotalTokenSupply
    // R5: Long             PrecisionFactor
    // R6: Long             MinBankValue
    // R7: Long             BankFeeNum
    // R8: Long             DevFeeNum

    // ===== Relevant Transactions ===== //
    // 1. Mint Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, MinerFee, TxOperatorFee
    // Context Variables: None
    // 2. Burn Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, PhoenixFee, MinerFee, TxOperatorFee
    // Context Variables: None

    // ===== Compile Time Constants ($) ===== //
    // $phoenixFeeContractBytesHash: Coll[Byte]

    // ===== Context Variables (_) ===== //
    // None

    // ===== Relevant Variables ===== //
    val totalTokenSupply: Long      = SELF.R4[Long].get
    val precisionFactor: Long       = SELF.R5[Long].get
    val minBankValue: Long          = SELF.R6[Long].get
    val devFeeNum: Long             = SELF.R7[Long].get
    val bankFeeNum: Long            = SELF.R8[Long].get
    val feeDenom: Long              = 1000L

    // Bank Input
    val reserveIn: Long         = SELF.value
    val hodlERGIn: Long         = SELF.tokens(1)._2               // hodlERG token amount in the bank box.
    val hodlERGCircIn: Long     = totalTokenSupply - hodlERGIn    // hodlERG in circulation since this value represents what is not inside the box, this must not ever be 0.

    // Bank Output
    val bankBoxOUT: Box     = OUTPUTS(0)
    val reserveOut: Long    = bankBoxOUT.value
    val hodlERGOut: Long    = bankBoxOUT.tokens(1)._2

    // Bank Info
    val hodlERGCircDelta: Long      = hodlERGIn - hodlERGOut // When minting hodlCoin, this is the amount of coins the buyer gets.
    val price: BigInt               = (reserveIn.toBigInt * precisionFactor) / hodlERGCircIn
    val isMintTx: Boolean           = (hodlERGCircDelta > 0L)

    val validBankRecreation: Boolean = {

        val validValue: Boolean = (bankBoxOUT.value >= minBankValue) // There must be at least 1 ERG always in the box

        val validContract: Boolean = (bankBoxOUT.propositionBytes == SELF.propositionBytes)

        val validTokens: Boolean = {

            val validBankSingleton: Boolean = (bankBoxOUT.tokens(0) == SELF.tokens(0))          // Singleton token amount never changes
            val validHodlERGTokenId: Boolean = (bankBoxOUT.tokens(1)._1 == SELF.tokens(1)._1)
            val validHodlERGTokenAmount: Boolean = (bankBoxOUT.tokens(1)._2 >= 1L)              // HodlCoin token amount can change, but there must be 1 hodlerg inside the bank always

            allOf(Coll(
                validBankSingleton,
                validHodlERGTokenId,
                validHodlERGTokenAmount
            ))

        }

        val validRegisters: Boolean = {

            allOf(Coll(
                (bankBoxOUT.R4[Long].get == SELF.R4[Long].get),
                (bankBoxOUT.R5[Long].get == SELF.R5[Long].get),
                (bankBoxOUT.R6[Long].get == SELF.R6[Long].get),
                (bankBoxOUT.R7[Long].get == SELF.R7[Long].get),
                (bankBoxOUT.R8[Long].get == SELF.R8[Long].get)
            ))

        }

        allOf(Coll(
            validValue,
            validContract,
            validTokens,
            validRegisters
        ))

    }

    if (isMintTx) {

        // ===== Mint Tx ===== //
        val validMintTx: Boolean = {

            val expectedAmountDeposited: Long = (hodlERGCircDelta * price) / precisionFactor // Price of hodlCoin in nanoERG.

            val validBankDeposit: Boolean = (reserveOut >= reserveIn + expectedAmountDeposited)

            allOf(Coll(
                validBankRecreation,
                validBankDeposit
            ))

        }

        sigmaProp(validMintTx)

    } else {

        // ===== Burn Tx ===== //
        val validBurnTx: Boolean = {

            // Outputs
            val phoenixFeeBoxOUT: Box = OUTPUTS(2)

            val hodlCoinsBurned: Long = hodlERGOut - hodlERGIn
            val expectedAmountBeforeFees: Long = (hodlCoinsBurned * price) / precisionFactor
            val bankFeeAmount: Long = (expectedAmountBeforeFees * bankFeeNum) / feeDenom
            val devFeeAmount: Long = (expectedAmountBeforeFees * devFeeNum) / feeDenom
            val expectedUserAmount: Long = expectedAmountBeforeFees - bankFeeAmount - devFeeAmount // The buyer never gets the bankFeeAmount since it remains in the bank box.

            val validBankWithdraw: Boolean = (reserveOut == reserveIn - expectedAmountBeforeFees + bankFeeAmount)

            val validPhoenixFee: Boolean = {

                allOf(Coll(
                    (phoenixFeeBoxOUT.value == devFeeAmount),
                    (blake2b256(phoenixFeeBoxOUT.propositionBytes) == $phoenixFeeContractBytesHash)
                ))

            }

            allOf(Coll(
                validBankRecreation,
                validBankWithdraw,
                validPhoenixFee
            ))

        }

        sigmaProp(validBurnTx)

    }

}

{

    // ===== Contract Information ===== //
    // Name: Phoenix HodlERG Proxy
    // Description: Contract guarding the proxy box for the hodlERG protocol.
    // Version: 1.0.0
    // Author: Luca D'Angelo (ldgaetano@protonmail.com), MGPai

    // ===== Box Contents ===== //
    // Tokens
    // 1. (HodlERGTokenId, HodlERGTokenAmount) if burning hodlERG tokens.
    // Registers
    // R4: SigmaProp    BuyerPK
    // R5: Coll[Byte]   BankSingletonTokenId
    // R6: Coll[Byte]   HodlERGTokenId
    // R7: Long         MinBoxValue
    // R8: Long         MinerFee
    // R9: Long         TxOperatorFee

    // ===== Relevant Transactions ===== //
    // 1. Mint Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, MinerFee, TxOperatorFee
    // Context Variables: None
    // 2. Burn Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, PhoenixFee, MinerFee, TxOperatorFee
    // Context Variables: None
    // 3. Refund Tx
    // Inputs: Proxy
    // Data Inputs: None
    // Outputs: BuyerPK, MinerFee
    // Context Variables: None

    // ===== Compile Time Constants ($) ===== //
    // $minTxOperatorFee: Long

    // ===== Context Variables (_) ===== //
    // None

    // ===== Relevant Variables ===== //
    val buyerPK: SigmaProp                      = SELF.R4[SigmaProp].get
    val bankSingletonTokenId: Coll[Byte]        = SELF.R5[Coll[Byte]].get
    val hodlERGTokenId: Coll[Byte]              = SELF.R6[Coll[Byte]].get
    val minBoxValue: Long                       = SELF.R7[Long].get
    val minerFee: Long                          = SELF.R8[Long].get
    val txOperatorFee: Long                     = SELF.R9[Long].get
    val minerFeeErgoTreeBytesHash: Coll[Byte]   = fromBase16("e540cceffd3b8dd0f401193576cc413467039695969427df94454193dddfb375")
    val isValidBank: Boolean                    = (INPUTS(0).tokens.size > 1 && INPUTS(0).tokens(0)._1 == bankSingletonTokenId) && (INPUTS(0).tokens(1)._1 == hodlERGTokenId)

    if (isValidBank) {

        // Bank Input
        val bankBoxIN: Box              = INPUTS(0)
        val reserveIn: Long             = bankBoxIN.value
        val hodlERGIn: Long             = bankBoxIN.tokens(1)._2
        val totalTokenSupply: Long      = bankBoxIN.R4[Long].get
        val precisionFactor: Long       = bankBoxIN.R5[Long].get
        val bankFeeNum: Long            = bankBoxIN.R7[Long].get
        val devFeeNum: Long             = bankBoxIN.R8[Long].get
        val feeDenom: Long              = 1000L
        val hodlERGCircIn: Long         = totalTokenSupply - hodlERGIn

        // Bank Output
        val bankBoxOUT: Box  = OUTPUTS(0)
        val reserveOut: Long = bankBoxOUT.value
        val hodlERGOut: Long = bankBoxOUT.tokens(1)._2

        // Bank Info
        val hodlERGCircDelta: Long      = hodlERGIn - hodlERGOut
        val price: BigInt               = (reserveIn.toBigInt * precisionFactor) / hodlERGCircIn
        val isMintTx: Boolean           = (hodlERGCircDelta > 0L)

        // Outputs
        val buyerPKBoxOUT: Box = OUTPUTS(1)

        if (isMintTx) {

            // ===== Mint Tx ===== //
            val validMintTx: Boolean = {

                // Outputs
                val minerFeeBoxOUT: Box = OUTPUTS(2)
                val txOperatorFeeBoxOUT: Box = OUTPUTS(3)

                val expectedAmountDeposited: Long = (hodlERGCircDelta * price) / precisionFactor

                val validProxyValue: Boolean = (SELF.value - minBoxValue - minerFee - txOperatorFee >= expectedAmountDeposited)

                val validBuyerBoxOUT: Boolean = {

                    val validValue: Boolean = (buyerPKBoxOUT.value == minBoxValue)
                    val validContract: Boolean = (buyerPKBoxOUT.propositionBytes == buyerPK.propBytes)
                    val validHodlCoinTransfer: Boolean = (buyerPKBoxOUT.tokens(0) == (bankBoxOUT.tokens(1)._1, hodlERGCircDelta))

                    allOf(Coll(
                        validValue,
                        validContract,
                        validHodlCoinTransfer
                    ))

                }

                val validMinerFee: Boolean = {

                    allOf(Coll(
                        (minerFeeBoxOUT.value == minerFee),
                        (blake2b256(minerFeeBoxOUT.propositionBytes) == minerFeeErgoTreeBytesHash)
                    ))

                }

                val validTxOperatorFee: Boolean = {

                    allOf(Coll(
                        (txOperatorFee >= $minTxOperatorFee),
                        (txOperatorFeeBoxOUT.value == txOperatorFee)
                    ))

                }

                val validOutputSize: Boolean = (OUTPUTS.size == 4)

                allOf(Coll(
                    validProxyValue,
                    validBuyerBoxOUT,
                    validMinerFee,
                    validTxOperatorFee,
                    validOutputSize
                ))

            }

            sigmaProp(validMintTx)

        } else {

            // ===== Burn Tx ===== //
            val validBurnTx: Boolean = {

                // Outputs
                val phoenixFeeBoxOUT: Box = OUTPUTS(2)
                val minerFeeBoxOUT: Box = OUTPUTS(3)
                val txOperatorFeeBoxOUT: Box = OUTPUTS(4)

                val hodlCoinsBurned: Long = hodlERGOut - hodlERGIn
                val expectedAmountBeforeFees: Long = (hodlCoinsBurned * price) / precisionFactor
                val bankFeeAmount: Long = (expectedAmountBeforeFees * bankFeeNum) / feeDenom
                val devFeeAmount: Long = (expectedAmountBeforeFees * devFeeNum) / feeDenom
                val expectedAmountWithdrawn: Long = expectedAmountBeforeFees - bankFeeAmount - devFeeAmount

                val validBurn: Boolean = (bankBoxOUT.tokens(1)._2 == bankBoxIN.tokens(1)._2 + SELF.tokens(0)._2)

                val validBuyerBoxOUT: Boolean = {

                    val validERGTransfer: Boolean = (buyerPKBoxOUT.value == expectedAmountWithdrawn)
                    val validContract: Boolean = (buyerPKBoxOUT.propositionBytes == buyerPK.propBytes)

                    allOf(Coll(
                        validERGTransfer,
                        validContract
                    ))

                }

                val validMinerFee: Boolean = {

                    allOf(Coll(
                        (minerFeeBoxOUT.value == minerFee),
                        (blake2b256(minerFeeBoxOUT.propositionBytes) == minerFeeErgoTreeBytesHash)
                    ))

                }

                val validTxOperatorFee: Boolean = {

                    allOf(Coll(
                        (txOperatorFee >= $minTxOperatorFee),
                        (txOperatorFeeBoxOUT.value == txOperatorFee)
                    ))

                }

                val validOutputSize: Boolean = (OUTPUTS.size == 5)

                allOf(Coll(
                    validBurn,
                    validBuyerBoxOUT,
                    validMinerFee,
                    validTxOperatorFee,
                    validOutputSize
                ))

            }

            sigmaProp(validBurnTx)

        }

    } else {

        // ===== Refund Tx ===== //
        val validRefundTx: Boolean = {

            val validBuyerBoxOUT: Boolean = {

                // Ensure that the buyer receives the total value of box.
                val validValueTransfer: Boolean = {

                    OUTPUTS.map({ (o: Box) =>
                        if (o.propositionBytes == buyerPK.propBytes) o.value else 0L
                    }).fold(0L, { (a: Long, b: Long) => a + b }) >= SELF.value

                }

                // If the box has tokens in it, all must go to buyer.
                val validTokenTransfer: Boolean = {

                    if (SELF.tokens.size > 0) {

                        OUTPUTS.exists({ (o: Box) =>
                            (o.tokens == SELF.tokens) && (o.propositionBytes == buyerPK.propBytes)
                        })

                    } else {
                      true
                    }

                }

                allOf(Coll(
                    validValueTransfer,
                    validTokenTransfer
                ))

            }

            validBuyerBoxOUT

        }

        sigmaProp(validRefundTx) && buyerPK

    }

}

{

    // ===== Contract Information ===== //
    // Name: Phoenix HodlToken Bank
    // Description: Contract for the bank box of the hodlToken protocol.
    // Version: 1.0.0
    // Author: Luca D'Angelo (ldgaetano@protonmail.com), MGPai, Kushti

    // ===== Box Contents ===== //
    // Tokens
    // 1. (BankSingletonId, 1)
    // 2. (HodlTokenId, HodlTokenAmount)
    // 3. (BaseTokenId, BaseTokenAmount)
    // Registers
    // R4: Long             TotalTokenSupply
    // R5: Long             PrecisionFactor
    // R6: Long             MinBankValue
    // R7: Long             BankFeeNum
    // R8: Long             DevFeeNum

    // ===== Relevant Transactions ===== //
    // 1. Mint Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, MinerFee, TxOperatorFee
    // Context Variables: None
    // 2. Burn Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, PhoenixFee, MinerFee, TxOperatorFee
    // Context Variables: None
    // 3. Reserve Deposit Tx
    // Inputs: Bank, Proxy
    // Data Input: None
    // Outputs: Bank, MinerFee, TxOperatorFee
    // Context Variables: None

    // ===== Compile Time Constants ($) ===== //
    // $phoenixFeeContractBytesHash: Coll[Byte]

    // ===== Context Variables (_) ===== //
    // None

    // ===== User Defined Methods ===== //
    // divUp: (BigInt, BigInt) => BigInt

    // Integer division, rounded up.
    def divUp(operands: (BigInt, BigInt)): BigInt = {

        val a: BigInt = operands._1 // Dividend
        val b: BigInt = operands._2 // Divisor

        if (b == 0.toBigInt) {
            -1.toBigInt
        } else {
            (a + (b-1.toBigInt)) / b
        }

    } 

    // ===== Relevant Variables ===== //
    val totalTokenSupply: Long      = SELF.R4[Long].get
    val precisionFactor: Long       = SELF.R5[Long].get // If the token does not have decimals, i.e. decimals = 0 when minted, then the precision factor should be set to 1.
    val minBankValue: Long          = SELF.R6[Long].get
    val devFeeNum: Long             = SELF.R7[Long].get
    val bankFeeNum: Long            = SELF.R8[Long].get
    val feeDenom: BigInt            = 1000.toBigInt

    // Bank Input
    val hodlTokensIn: Long       = SELF.tokens(1)._2                // hodlToken token amount in the bank box.
    val reserveIn: Long          = SELF.tokens(2)._2                // Amount of base token in the bank box
    val hodlTokensCircIn: Long   = totalTokenSupply - hodlTokensIn  // hodlToken in circulation since this value represents what is not inside the box, this must not ever be 0.

    // Bank Output
    val bankBoxOUT: Box      = OUTPUTS(0)
    val reserveOut: Long     = bankBoxOUT.tokens(2)._2
    val hodlTokensOut: Long  = bankBoxOUT.tokens(1)._2

    // Bank Info
    val hodlTokensCircDelta: Long   = hodlTokensIn - hodlTokensOut                                  // When minting hodlToken, this is the amount of coins the buyer gets.
    val price: BigInt               = (reserveIn.toBigInt * precisionFactor) / hodlTokensCircIn
    val isMintTx: Boolean           = (hodlTokensCircDelta > 0L)                                    // hodlToken supply increases + baseToken reserve increases
    val isBurnTx: Boolean           = (hodlTokensCircDelta < 0L)                                    // hodlToken supply decreases + baseToken reserve decreases
    val isDepositTx: Boolean        = (hodlTokensCircDelta == 0L)                                   // baseToken reserve increases

    val validBankRecreation: Boolean = {

        val validValue: Boolean = (bankBoxOUT.value == SELF.value) // ERG value in bank box should not change for any reason, since HoldToken version of HodlCoin has nothing to do with ERG.

        val validContract: Boolean = (bankBoxOUT.propositionBytes == SELF.propositionBytes)

        val validTokens: Boolean = {

            val validBankSingleton: Boolean = (bankBoxOUT.tokens(0) == SELF.tokens(0))          // Singleton token amount never changes
            val validHodlTokenId: Boolean = (bankBoxOUT.tokens(1)._1 == SELF.tokens(1)._1)
            val validHodlTokenAmount: Boolean = (hodlTokensOut >= 1L)                           // HodlToken token amount can change, but there must be 1 hodlerg inside the bank always
            val validBaseTokenId: Boolean = (bankBoxOUT.tokens(2)._1 == SELF.tokens(2)._1)
            val validBaseTokenMinBankValue: Boolean = (reserveOut >= minBankValue)              // The bank must have a minimum value of the base token.

            allOf(Coll(
                validBankSingleton,
                validHodlTokenId,
                validHodlTokenAmount,
                validBaseTokenId,
                validBaseTokenMinBankValue
            ))

        }

        val validRegisters: Boolean = {

            allOf(Coll(
                (bankBoxOUT.R4[Long].get == SELF.R4[Long].get),
                (bankBoxOUT.R5[Long].get == SELF.R5[Long].get),
                (bankBoxOUT.R6[Long].get == SELF.R6[Long].get),
                (bankBoxOUT.R7[Long].get == SELF.R7[Long].get),
                (bankBoxOUT.R8[Long].get == SELF.R8[Long].get)
            ))

        }

        allOf(Coll(
            validValue,
            validContract,
            validTokens,
            validRegisters
        ))

    }

    if (isMintTx) {

        // ===== Mint Tx ===== //
        val validMintTx: Boolean = {

            val expectedAmountDeposited: Long = (hodlTokensCircDelta * price) / precisionFactor // Price of hodlCoin in nanoERG.

            val validTokenDeposit: Boolean = (reserveOut >= reserveIn + expectedAmountDeposited)

            allOf(Coll(
                validBankRecreation,
                validTokenDeposit
            ))

        }

        sigmaProp(validMintTx)

    } else if (isBurnTx) {

        // ===== Burn Tx ===== //
        val validBurnTx: Boolean = {

            val hodlTokensBurned: Long = hodlTokensOut - hodlTokensIn
            val expectedAmountBeforeFees: Long = (hodlTokensBurned * price) / precisionFactor // X: Here we convert the amount of hodlTokens burned into the amount of base tokens released from the bank.

            val dividend_1: BigInt = (expectedAmountBeforeFees.toBigInt * (bankFeeNum.toBigInt + devFeeNum.toBigInt)) // Here we want to determine the amount allocated to the bank and to the developers.
            val divisor_1: BigInt = feeDenom // This is never zero.

            val bankFeeAndDevFeeAmount: BigInt = divUp((dividend_1, divisor_1)) // Y: Here we use the divUp method to perform integer division in order to compute the combined bank fee and developer fee without integer division errors.

            val dividend_2: BigInt = (bankFeeAndDevFeeAmount.toBigInt * devFeeNum.toBigInt) // Here we want to determine the allocation of the developers from the total bank fee and developer fee.
            val divisor_2: BigInt = (bankFeeNum.toBigInt + devFeeNum.toBigInt) // This is never zero, devFeeNum can be zero but bankFeeNum cannot.

            val devFeeAmount: BigInt = divUp((dividend_2, divisor_2)) // Z: Here we use the divUp method to perform integer division in order to compute the developer fee allocation without integer division errors.
            val bankFeeAmount: BigInt = bankFeeAndDevFeeAmount - devFeeAmount // Y - Z: Using the the combined bank fee and developer fee and the isolated developer fee, we compute the remaining amount which is the bank fee allocation.

            // Here we adjust the developer fee and bank fee amounts so that the bank fee is never 0, we do this to preserve the game mechanics of the protocol, i.e. that the price always increases.
            val devFeeAmountAdjusted: BigInt = if (bankFeeAmount == 0.toBigInt) 0.toBigInt else devFeeAmount
            val bankFeeAmountAdjusted: BigInt = if (bankFeeAmount == 0.toBigInt) devFeeAmount else bankFeeAmount

            val expectedUserAmount: BigInt = expectedAmountBeforeFees - bankFeeAndDevFeeAmount // X - Y: The buyer never gets the bankFeeAmount since it remains in the bank box.

            val validBankWithdraw: Boolean = (reserveOut.toBigInt == reserveIn.toBigInt - expectedAmountBeforeFees + bankFeeAmountAdjusted)

            val validPhoenixFee: Boolean = {

                if (devFeeAmountAdjusted != 0.toBigInt) {

                    val phoenixFeeBoxOUT: Box = OUTPUTS(2)

                    allOf(Coll(
                        (phoenixFeeBoxOUT.tokens(0)._1 == SELF.tokens(2)._1),
                        (phoenixFeeBoxOUT.tokens(0)._2 == devFeeAmountAdjusted),
                        (blake2b256(phoenixFeeBoxOUT.propositionBytes) == $phoenixFeeContractBytesHash)
                    ))

                } else {
                    true
                }

            }

            allOf(Coll(
                validBankRecreation,
                validBankWithdraw,
                validPhoenixFee
            ))

        }

        sigmaProp(validBurnTx)

    } else if (isDepositTx) {

        // ===== Reseve Deposit Tx ===== //
        val validReserveDepositTx: Boolean = {

           val validReserveIncrease: Boolean = (reserveOut > reserveIn) // The bank baseToken reserve must increase, nothing else happens.

           allOf(Coll(
            validBankRecreation,
            validReserveIncrease
           ))

        }

        sigmaProp(validReserveDepositTx)

    } else {
        sigmaProp(false)
    }

}

{

    // ===== Contract Information ===== //
    // Name: Phoenix HodlCoin Bank
    // Description: Contract for the bank box of the HodlCoin protocol.
    // Version: 1.0.0
    // Author: Luca D'Angelo (ldgaetano@protonmail.com), MGPai

    // ===== Box Contents ===== //
    // Tokens
    // 1. (BankSingletonId, 1)
    // 2. (HodlCoinTokenId, HodlCoinTokenAmount)
    // Registers
    // R4: Long             TotalTokenSupply
    // R5: Long             PrecisionFactor
    // R6: Long             MinBankValue
    // R7: Long             BankFeeNum
    // R8: Long             DevFeeNum

    // ===== Relevant Transactions ===== //
    // 1. Mint Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, MinerFee, TxOperatorFee
    // Context Variables: None
    // 2. Burn Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, PhoenixFee, MinerFee, TxOperatorFee
    // Context Variables: None

    // ===== Compile Time Constants ($) ===== //
    // $phoenixFeeContractBytesHash: Coll[Byte]

    // ===== Context Variables (@) ===== //
    // None

    // ===== Relevant Variables ===== //
    val totalTokenSupply: Long      = SELF.R4[Long].get
    val precisionFactor: Long       = SELF.R5[Long].get
    val minBankValue: Long          = SELF.R6[Long].get
    val devFeeNum: Long             = SELF.R7[Long].get
    val bankFeeNum: Long            = SELF.R8[Long].get
    val feeDenom: Long              = 1000L

    // Bank Input
    val reserveIn: Long         = SELF.value
    val hodlCoinsIn: Long       = SELF.tokens(1)._2               // hodlERG token amount in the bank box.
    val hodlCoinsCircIn: Long   = totalTokenSupply - hodlCoinsIn  // hodlERG in circulation since this value represents what is not inside the box, this must not ever be 0.

    // Bank Output
    val bankBoxOUT: Box     = OUTPUTS(0)
    val reserveOut: Long    = bankBoxOUT.value
    val hodlCoinsOut: Long  = bankBoxOUT.tokens(1)._2

    // Bank Info
    val hodlCoinsCircDelta: Long    = hodlCoinsIn - hodlCoinsOut // When minting hodlCoin, this is the amount of coins the buyer gets.
    val price: Long                 = (reserveIn.toBigInt * precisionFactor) / hodlCoinsCircIn
    val isMintTx: Boolean           = (hodlCoinsCircDelta > 0L)

    val validBankRecreation: Boolean = {

        val validValue: Boolean = (bankBoxOUT.value >= minBankValue) // There must be at least 1 ERG always in the box

        val validContract: Boolean = (bankBoxOUT.propositionBytes == SELF.propositionBytes)

        val validTokens: Boolean = {

            val validBankSingleton: Boolean = (bankBoxOUT.tokens(0) == SELF.tokens(0))          // Singleton token amount never changes
            val validHodlCoinTokenId: Boolean = (bankBoxOUT.tokens(1)._1 == SELF.tokens(1)._1)
            val validHodlCoinTokenAmount: Boolean = (bankBoxOUT.tokens(1)._2 >= 1L)             // HodlCoin token amount can change, but there must be 1 hodlerg inside the bank always

            allOf(Coll(
                validBankSingleton,
                validHodlCoinTokenId,
                validHodlCoinTokenAmount
            ))

        }

        val validRegisters: Boolean = {

            allOf(Coll(
                (bankBoxOUT.R4[Long].get == SELF.R4[Long].get),
                (bankBoxOUT.R5[Long].get == SELF.R5[Long].get),
                (bankBoxOUT.R6[Long].get == SELF.R6[Long].get),
                (bankBoxOUT.R7[Long].get == SELF.R7[Long].get),
                (bankBoxOUT.R8[Long].get == SELF.R8[Long].get)
            ))

        }

        allOf(Coll(
            validValue,
            validContract,
            validTokens,
            validRegisters
        ))

    }

    if (isMintTx) {

        // ===== Mint Tx ===== //
        val validMintTx: Boolean = {

            val expectedAmountDeposited: Long = (hodlCoinsCircDelta * price) / precisionFactor // Price of hodlCoin in nanoERG.

            val validBankDeposit: Boolean = (reserveOut >= reserveIn + expectedAmountDeposited)

            allOf(Coll(
                validBankRecreation,
                validBankDeposit
            ))

        }

        sigmaProp(validMintTx)

    } else {

        // ===== Burn Tx ===== //
        val validBurnTx: Boolean = {

            // Outputs
            val phoenixFeeBoxOUT: Box = OUTPUTS(2)

            val hodlCoinsBurned: Long = hodlCoinsOut - hodlCoinsIn
            val expectedAmountBeforeFees: Long = (hodlCoinsBurned * price) / precisionFactor
            val bankFeeAmount: Long = (expectedAmountBeforeFees * bankFeeNum) / feeDenom
            val devFeeAmount: Long = (expectedAmountBeforeFees * devFeeNum) / feeDenom
            val expectedUserAmount: Long = expectedAmountBeforeFees - bankFeeAmount - devFeeAmount // The buyer never gets the bankFeeAmount since it remains in the bank box.

            val validBankWithdraw: Boolean = (reserveOut == reserveIn - expectedAmountBeforeFees + bankFeeAmount) // What should have left the bank is the amount the user got plus the bank fee amount which must remain in the bank.

            val validPhoenixFee: Boolean = {

                allOf(Coll(
                    (phoenixFeeBoxOUT.value == devFeeAmount),
                    (blake2b256(phoenixFeeBoxOUT.propositionBytes) == $phoenixFeeContractBytesHash)
                ))

            }

            allOf(Coll(
                validBankRecreation,
                validBankWithdraw,
                validPhoenixFee
            ))

        }

        sigmaProp(validBurnTx)

    }

}

{

    // ===== Contract Information ===== //
    // Name: Phoenix HodlCoin Proxy
    // Description: Contract guarding the proxy box for the HodlCoin protocol.
    // Version: 1.0.0
    // Author: Luca D'Angelo (ldgaetano@protonmail.com), MGPai

    // ===== Box Contents ===== //
    // Tokens
    // 1. (HodlCoinTokenId, HodlCoinTokenAmount) if burning hodlCoin tokens.
    // Registers
    // R4: SigmaProp    BuyerPK
    // R5: Coll[Byte]   BankSingletonTokenId
    // R6: Coll[Byte]   HodlCoinTokenId
    // R7: Long         MinBoxValue
    // R8: Long         MinerFee
    // R9: Long         TxOperatorFee

    // ===== Relevant Transactions ===== //
    // 1. Mint Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, MinerFee, TxOperatorFee
    // Context Variables: None
    // 2. Burn Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, PhoenixFee, MinerFee, TxOperatorFee
    // Context Variables: None
    // 3. Refund Tx
    // Inputs: Proxy
    // Data Inputs: None
    // Outputs: BuyerPK, MinerFee
    // Context Variables: None

    // ===== Compile Time Constants ($) ===== //
    // $minTxOperatorFee: Long

    // ===== Context Variables (@) ===== //
    // None

    // ===== Relevant Variables ===== //
    val buyerPK: SigmaProp                      = SELF.R4[SigmaProp].get
    val bankSingletonTokenId: Coll[Byte]        = SELF.R5[Coll[Byte]].get
    val hodlCoinTokenId: Coll[Byte]             = SELF.R6[Coll[Byte]].get
    val minBoxValue: Long                       = SELF.R7[Long].get
    val minerFee: Long                          = SELF.R8[Long].get
    val txOperatorFee: Long                     = SELF.R9[Long].get
    val minerFeeErgoTreeBytesHash: Coll[Byte]   = fromBase16("e540cceffd3b8dd0f401193576cc413467039695969427df94454193dddfb375")
    val isValidBank: Boolean                    = (INPUTS(0).tokens.size > 1 && INPUTS(0).tokens(0)._1 == bankSingletonTokenId) && (INPUTS(0).tokens(1)._1 == hodlCoinTokenId)

    if (isValidBank) {

        // Bank Input
        val bankBoxIN: Box              = INPUTS(0)
        val reserveIn: Long             = bankBoxIN.value
        val hodlCoinsIn: Long           = bankBoxIN.tokens(1)._2
        val totalTokenSupply: Long      = bankBoxIN.R4[Long].get
        val precisionFactor: Long       = bankBoxIN.R5[Long].get
        val bankFeeNum: Long            = bankBoxIN.R7[Long].get
        val devFeeNum: Long             = bankBoxIN.R8[Long].get
        val feeDenom: Long              = 1000L
        val hodlCoinsCircIn: Long       = totalTokenSupply - hodlCoinsIn

        // Bank Output
        val bankBoxOUT: Box     = OUTPUTS(0)
        val reserveOut: Long    = bankBoxOUT.value
        val hodlCoinsOut: Long  = bankBoxOUT.tokens(1)._2

        // Bank Info
        val hodlCoinsCircDelta: Long    = hodlCoinsIn - hodlCoinsOut
        val price: Long                 = (reserveIn.toBigInt * precisionFactor) / hodlCoinsCircIn
        val isMintTx: Boolean           = (hodlCoinsCircDelta > 0L)

        // Outputs
        val buyerPKBoxOUT: Box = OUTPUTS(1)

        if (isMintTx) {

            // ===== Mint Tx ===== //
            val validMintTx: Boolean = {

                // Outputs
                val minerFeeBoxOUT: Box = OUTPUTS(2)
            val txOperatorFeeBoxOUT: Box = OUTPUTS(3)

            val expectedAmountDeposited: Long = (hodlCoinsCircDelta * price) / precisionFactor

            val validProxyValue: Boolean = (SELF.value - minBoxValue - minerFee - txOperatorFee >= expectedAmountDeposited)

            val validBuyerBoxOUT: Boolean = {

                val validValue: Boolean = (buyerPKBoxOUT.value == minBoxValue)
            val validContract: Boolean = (buyerPKBoxOUT.propositionBytes == buyerPK.propBytes)
            val validHodlCoinTransfer: Boolean = (buyerPKBoxOUT.tokens(0) == (bankBoxOUT.tokens(1)._1, hodlCoinsCircDelta))

            allOf(Coll(
                validValue,
                validContract,
                validHodlCoinTransfer
            ))

        }

            val validMinerFee: Boolean = {

                allOf(Coll(
                    (minerFeeBoxOUT.value == minerFee),
                        (blake2b256(minerFeeBoxOUT.propositionBytes) == minerFeeErgoTreeBytesHash)
                ))

        }

            val validTxOperatorFee: Boolean = {

                allOf(Coll(
                    (txOperatorFee >= $minTxOperatorFee),
                        (txOperatorFeeBoxOUT.value == txOperatorFee)
                ))

        }

            val validOutputSize: Boolean = (OUTPUTS.size == 4)

            allOf(Coll(
                validProxyValue,
                validBuyerBoxOUT,
                validMinerFee,
                validTxOperatorFee,
                validOutputSize
            ))

        }

            sigmaProp(validMintTx)

        } else {

            // ===== Burn Tx ===== //
            val validBurnTx: Boolean = {

                // Outputs
                val phoenixFeeBoxOUT: Box = OUTPUTS(2)
            val minerFeeBoxOUT: Box = OUTPUTS(3)
            val txOperatorFeeBoxOUT: Box = OUTPUTS(4)

            val hodlCoinsBurned: Long = hodlCoinsOut - hodlCoinsIn
            val expectedAmountBeforeFees: Long = (hodlCoinsBurned * price) / precisionFactor
            val bankFeeAmount: Long = (expectedAmountBeforeFees * bankFeeNum) / feeDenom
            val devFeeAmount: Long = (expectedAmountBeforeFees * devFeeNum) / feeDenom
            val expectedAmountWithdrawn: Long = expectedAmountBeforeFees - bankFeeAmount - devFeeAmount

            val validBurn: Boolean = (bankBoxOUT.tokens(1)._2 == bankBoxIN.tokens(1)._2 + SELF.tokens(0)._2)

            val validBuyerBoxOUT: Boolean = {

                val validERGTransfer: Boolean = (buyerPKBoxOUT.value == expectedAmountWithdrawn)
            val validContract: Boolean = (buyerPKBoxOUT.propositionBytes == buyerPK.propBytes)

            allOf(Coll(
                validERGTransfer,
                validContract
            ))

        }

            val validMinerFee: Boolean = {

                allOf(Coll(
                    (minerFeeBoxOUT.value == minerFee),
                        (blake2b256(minerFeeBoxOUT.propositionBytes) == minerFeeErgoTreeBytesHash)
                ))

        }

            val validTxOperatorFee: Boolean = {

                allOf(Coll(
                    (txOperatorFee >= $minTxOperatorFee),
                        (txOperatorFeeBoxOUT.value == txOperatorFee)
                ))

        }

            val validOutputSize: Boolean = (OUTPUTS.size == 5)

            allOf(Coll(
                validBurn,
                validBuyerBoxOUT,
                validMinerFee,
                validTxOperatorFee,
                validOutputSize
            ))

        }

            sigmaProp(validBurnTx)

        }

    } else {

        // ===== Refund Tx ===== //
        val validRefundTx: Boolean = {

            val validBuyerBoxOUT: Boolean = {

            // Ensure that the buyer receives the total value of box.
            val validValueTransfer: Boolean = OUTPUTS.map { (o: Box) =>
            if (o.propositionBytes == buyerPK.propBytes) o.value else 0L
        }.fold(0L, { (a: Long, b: Long) => a + b }) >= SELF.value

        // If the box has tokens in it, all must go to buyer.
        val validTokenTransfer: Boolean = {
        if(SELF.tokens.size > 0){
            OUTPUTS.exists { (o: Box) =>
                (o.tokens == SELF.tokens) && (o.propositionBytes == buyerPK.propBytes)
            }
        } else{
            true
        }
    }

        allOf(Coll(
            validValueTransfer,
            validTokenTransfer
        ))

    }

        validBuyerBoxOUT

    }

        sigmaProp(validRefundTx) && buyerPK

    }

}

{

    // ===== Contract Information ===== //
    // Name: Phoenix HodlToken Bank
    // Description: Contract for the bank box of the hodlToken protocol.
    // Version: 1.0.0
    // Author: Luca D'Angelo (ldgaetano@protonmail.com), MGPai, Kushti

    // ===== Box Contents ===== //
    // Tokens
    // 1. (BankSingletonId, 1)
    // 2. (HodlTokenId, HodlTokenAmount)
    // 3. (BaseTokenId, BaseTokenAmount)
    // Registers
    // R4: Long             TotalTokenSupply
    // R5: Long             PrecisionFactor
    // R6: Long             MinBankValue
    // R7: Long             BankFeeNum
    // R8: Long             DevFeeNum

    // ===== Relevant Transactions ===== //
    // 1. Mint Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, MinerFee, TxOperatorFee
    // Context Variables: None
    // 2. Burn Tx
    // Inputs: Bank, Proxy
    // Data Inputs: None
    // Outputs: Bank, BuyerPK, PhoenixFee, MinerFee, TxOperatorFee
    // Context Variables: None
    // 3. Reserve Deposit Tx
    // Inputs: Bank, Proxy
    // Data Input: None
    // Outputs: Bank, MinerFee, TxOperatorFee
    // Context Variables: None

    // ===== Compile Time Constants ($) ===== //
    // $phoenixFeeContractBytes: Coll[Byte]

    // ===== Context Variables (_) ===== //
    // None

    // ===== User Defined Methods ===== //
    // divUp: (BigInt, BigInt) => BigInt

    // Integer division, rounded up.
    def divUp(operands: (BigInt, BigInt)): BigInt = {

        val a: BigInt = operands._1 // Dividend
        val b: BigInt = operands._2 // Divisor

        if (b == 0.toBigInt) {
            -1.toBigInt
        } else {
            (a + (b-1.toBigInt)) / b
        }

    }

    // ===== Relevant Variables ===== //
    val totalTokenSupply: Long      = SELF.R4[Long].get
    val precisionFactor: Long       = SELF.R5[Long].get // If the token does not have decimals, i.e. decimals = 0 when minted, then the precision factor should be set to 1.
    val minBankValue: Long          = SELF.R6[Long].get
    val devFeeNum: Long             = SELF.R7[Long].get
    val bankFeeNum: Long            = SELF.R8[Long].get
    val feeDenom: BigInt            = 1000.toBigInt

    // Bank Input
    val hodlTokensIn: Long       = SELF.tokens(1)._2                // hodlToken token amount in the bank box.
    val reserveIn: Long          = SELF.tokens(2)._2                // Amount of base token in the bank box
    val hodlTokensCircIn: Long   = totalTokenSupply - hodlTokensIn  // hodlToken in circulation since this value represents what is not inside the box, this must not ever be 0.

    // Bank Output
    val bankBoxOUT: Box      = OUTPUTS(0)
    val reserveOut: Long     = bankBoxOUT.tokens(2)._2
    val hodlTokensOut: Long  = bankBoxOUT.tokens(1)._2

    // Bank Info
    val hodlTokensCircDelta: Long   = hodlTokensIn - hodlTokensOut                                  // When minting hodlToken, this is the amount of coins the buyer gets.
    val price: BigInt               = (reserveIn.toBigInt * precisionFactor) / hodlTokensCircIn
    val isMintTx: Boolean           = (hodlTokensCircDelta > 0L)                                    // hodlToken supply increases + baseToken reserve increases
    val isBurnTx: Boolean           = (hodlTokensCircDelta < 0L)                                    // hodlToken supply decreases + baseToken reserve decreases
    val isDepositTx: Boolean        = (hodlTokensCircDelta == 0L)                                   // baseToken reserve increases

    val validBankRecreation: Boolean = {

        val validValue: Boolean = (bankBoxOUT.value == SELF.value) // ERG value in bank box should not change for any reason, since HoldToken version of HodlCoin has nothing to do with ERG.

        val validContract: Boolean = (bankBoxOUT.propositionBytes == SELF.propositionBytes)

        val validTokens: Boolean = {

            val validBankSingleton: Boolean = (bankBoxOUT.tokens(0) == SELF.tokens(0))          // Singleton token amount never changes
            val validHodlTokenId: Boolean = (bankBoxOUT.tokens(1)._1 == SELF.tokens(1)._1)
            val validHodlTokenAmount: Boolean = (hodlTokensOut >= 1L)                           // HodlToken token amount can change, but there must be 1 hodlerg inside the bank always
            val validBaseTokenId: Boolean = (bankBoxOUT.tokens(2)._1 == SELF.tokens(2)._1)
            val validBaseTokenMinBankValue: Boolean = (reserveOut >= minBankValue)              // The bank must have a minimum value of the base token.

            allOf(Coll(
                validBankSingleton,
                validHodlTokenId,
                validHodlTokenAmount,
                validBaseTokenId,
                validBaseTokenMinBankValue
            ))

        }

        val validRegisters: Boolean = {

            allOf(Coll(
                (bankBoxOUT.R4[Long].get == SELF.R4[Long].get),
                (bankBoxOUT.R5[Long].get == SELF.R5[Long].get),
                (bankBoxOUT.R6[Long].get == SELF.R6[Long].get),
                (bankBoxOUT.R7[Long].get == SELF.R7[Long].get),
                (bankBoxOUT.R8[Long].get == SELF.R8[Long].get)
            ))

        }

        allOf(Coll(
            validValue,
            validContract,
            validTokens,
            validRegisters
        ))

    }

    if (isMintTx) {

        // ===== Mint Tx ===== //
        val validMintTx: Boolean = {

            val expectedAmountDeposited: Long = (hodlTokensCircDelta * price) / precisionFactor // Price of hodlCoin in nanoERG.

            val validTokenDeposit: Boolean = (reserveOut >= reserveIn + expectedAmountDeposited)

            allOf(Coll(
                validBankRecreation,
                validTokenDeposit
            ))

        }

        sigmaProp(validMintTx)

    } else if (isBurnTx) {

        // ===== Burn Tx ===== //
        val validBurnTx: Boolean = {

            val hodlTokensBurned: Long = hodlTokensOut - hodlTokensIn
            val expectedAmountBeforeFees: Long = (hodlTokensBurned * price) / precisionFactor // X: Here we convert the amount of hodlTokens burned into the amount of base tokens released from the bank.

            val dividend_1: BigInt = (expectedAmountBeforeFees.toBigInt * (bankFeeNum.toBigInt + devFeeNum.toBigInt)) // Here we want to determine the amount allocated to the bank and to the developers.
            val divisor_1: BigInt = feeDenom // This is never zero.

            val bankFeeAndDevFeeAmount: BigInt = divUp((dividend_1, divisor_1)) // Y: Here we use the divUp method to perform integer division in order to compute the combined bank fee and developer fee without integer division errors.

            val dividend_2: BigInt = (bankFeeAndDevFeeAmount.toBigInt * devFeeNum.toBigInt) // Here we want to determine the allocation of the developers from the total bank fee and developer fee.
            val divisor_2: BigInt = (bankFeeNum.toBigInt + devFeeNum.toBigInt) // This is never zero, devFeeNum can be zero but bankFeeNum cannot.

            val devFeeAmount: BigInt = divUp((dividend_2, divisor_2)) // Z: Here we use the divUp method to perform integer division in order to compute the developer fee allocation without integer division errors.
            val bankFeeAmount: BigInt = bankFeeAndDevFeeAmount - devFeeAmount // Y - Z: Using the the combined bank fee and developer fee and the isolated developer fee, we compute the remaining amount which is the bank fee allocation.

            // Here we adjust the developer fee and bank fee amounts so that the bank fee is never 0, we do this to preserve the game mechanics of the protocol, i.e. that the price always increases.
            val devFeeAmountAdjusted: BigInt = if (bankFeeAmount == 0.toBigInt) 0.toBigInt else devFeeAmount
            val bankFeeAmountAdjusted: BigInt = if (bankFeeAmount == 0.toBigInt) devFeeAmount else bankFeeAmount

            val expectedUserAmount: BigInt = expectedAmountBeforeFees - bankFeeAndDevFeeAmount // X - Y: The buyer never gets the bankFeeAmount since it remains in the bank box.

            val validBankWithdraw: Boolean = (reserveOut.toBigInt == reserveIn.toBigInt - expectedAmountBeforeFees + bankFeeAmountAdjusted)

            val validPhoenixFee: Boolean = {

                if (devFeeAmountAdjusted != 0.toBigInt) {

                    val phoenixFeeBoxOUT: Box = OUTPUTS(2)

                    allOf(Coll(
                        (phoenixFeeBoxOUT.tokens(0)._1 == SELF.tokens(2)._1),
                        (phoenixFeeBoxOUT.tokens(0)._2 == devFeeAmountAdjusted),
                        (phoenixFeeBoxOUT.propositionBytes == $phoenixFeeContractBytes)
                    ))

                } else {
                    true
                }

            }

            allOf(Coll(
                validBankRecreation,
                validBankWithdraw,
                validPhoenixFee
            ))

        }

        sigmaProp(validBurnTx)

    } else if (isDepositTx) {

        // ===== Reseve Deposit Tx ===== //
        val validReserveDepositTx: Boolean = {

           val validReserveIncrease: Boolean = (reserveOut > reserveIn) // The bank baseToken reserve must increase, nothing else happens.

           allOf(Coll(
            validBankRecreation,
            validReserveIncrease
           ))

        }

        sigmaProp(validReserveDepositTx)

    } else {
        sigmaProp(false)
    }

}

