{
  // Bank script
  //
  // This box: (Bank box)
  //
  // TOKENS
  //   tokens(0): bankNFT identifying the box
  //   tokens(1): dexyUSD tokens to be emitted
  // REGISTERS
  //   None
  //
  // TRANSACTIONS
  //
  // [1] Arbitrage Mint
  //   Input         |  Output         |   Data-Input
  // ------------------------------------------------
  // 0 ArbitrageMint |  ArbitrageMint  |   Oracle
  // 1 Bank          |  Bank           |   LP
  // 2 Buyback       |  Buyback        |
  //
  // [2] Free Mint
  //   Input    |  Output   |   Data-Input
  // -------------------------------------
  // 0 FreeMint |  FreeMint |   Oracle
  // 1 Bank     |  Bank     |   LP
  // 2 Buyback  |  Buyback  |
  //
  // [3] Intervention
  //   Input         |  Output        |   Data-Input
  // -----------------------------------------------
  // 0 LP            |  LP            |   Oracle
  // 1 Bank          |  Bank          |   Tracking (98%)
  // 2 Intervention  |  Intervention  |
  //
  // [4] Payout
  //   Input         |  Output        |   Data-Input
  // -----------------------------------------------
  // 0 Payout        |  Payout        |   Oracle
  // 1 Bank          |  Bank          |
  // 2 Buyback       |  Buyback       |

  // [5] Update
  //   Input         |  Output        |   Data-Input
  // -----------------------------------------------
  // 0 Update        |  Update        |
  // 1 Bank          |  Bank          |

  // This box emits DexyUSD. The contract only enforces some basic rules (such as the contract and token Ids) are preserved.
  // It does not does not encode the emission logic. It just requires certain boxes in the inputs to contain certain NFTs.
  // Those boxes in turn encode the emission logic (and logic for other auxiliary flows, such as intervention).
  // The minting logic (that emits Dexy tokens) is encoded in the FreeMint and ArbitrageMint boxes

  // Oracle data:
  // R4 of the oracle contains the rate "nanoErgs per USD" in Long format

  // inputs indices
  val mintInIndex = 0         // 1st input is mint (or LP box in case of intervention, which we ensure in intervention box)
  val interventionInIndex = 2 // 3rd input is intervention box
  val payoutInIndex = 0       // 1st input is payout box

  // outputs indices
  val selfOutIndex = 1        // 2nd output is self copy

  val freeMintNFT = fromBase64("0101010101010101010101010101010101010101010101010101010101010101")
  val arbitrageMintNFT = fromBase64("0202020202020202020202020202020202020202020202020202020202020202")
  val interventionNFT = fromBase64("0303030303030303030303030303030303030303030303030303030303030303")
  val payoutNFT = fromBase64("0404040404040404040404040404040404040404040404040404040404040404")

  val successor = OUTPUTS(selfOutIndex)

  val validSuccessor = successor.tokens(0) == SELF.tokens(0)                && // NFT preserved
                       successor.propositionBytes == SELF.propositionBytes  && // script preserved
                       successor.tokens(1)._1 == SELF.tokens(1)._1             // dexyUSD token Id preserved (but amount will change)

  val validMint = INPUTS(mintInIndex).tokens(0)._1 == freeMintNFT        ||
                  INPUTS(mintInIndex).tokens(0)._1 == arbitrageMintNFT

  val validIntervention = INPUTS(interventionInIndex).tokens(0)._1 == interventionNFT

  val validPayout = INPUTS(payoutInIndex).tokens(0)._1 == payoutNFT

  val updateNFT = fromBase64("0505050505050505050505050505050505050505050505050505050505050505")
  val validUpdate = INPUTS(0).tokens(0)._1 == updateNFT

  sigmaProp((validSuccessor && (validMint || validIntervention || validPayout)) || validUpdate)
}

{ // This box (ballot box):
  // R4 the group element of the owner of the ballot token [GroupElement]
  // R5 the box id of the update box [Coll[Byte]]
  // R6 the value voted for [Coll[Byte]]

  val updateNFT = fromBase64("0101010101010101010101010101010101010101010101010101010101010101")

  val pubKey = SELF.R4[GroupElement].get

  val index = INPUTS.indexOf(SELF, 0)

  val output = OUTPUTS(index)

  val isBasicCopy = output.R4[GroupElement].get == pubKey && // todo: change to .isDefined so pubkey rotation possible?
                    output.propositionBytes == SELF.propositionBytes &&
                    output.tokens == SELF.tokens &&
                    output.value >= SELF.value

  val castVote = proveDlog(pubKey)

  val notVoted = output.R5[Coll[Byte]].isDefined == false
  val update = INPUTS(0).tokens(0)._1 == updateNFT && notVoted

  // Note: We want that during an update, a new valid vote should not be generated
  // notVoted ensures that the update action does not generate a new vote.
  // This is already prevented by having R5 contain the id of the update box,
  // This guarantees that R5 can never contain this box Id (because it depends on the outputs)
  // However, notVoted is used for additional security

  sigmaProp(
    isBasicCopy && (castVote || update)
  )
}

{
  // Contract which is releasing GORT to developers (Gold cooperative), 1 ERG per block.
  // It supports two actions: top-up and withdrawal

  // Registers:
  // R4 (int) - last payment height
  // R5 (SigmaProp) - auth

  // tokens:
  // #0 - box id NFT
  // #1 - GORT

  // context vars:
  // #0 - output index of SELF
  // #1 - action (top-up / withdrawal)

  val lastHeight = SELF.R4[Int].get // last payout height

  val selfOutIndex = getVar[Short](0).get

  val selfOut = OUTPUTS(selfOutIndex)

  // strip header byte from trees
  val selfOutTree = selfOut.propositionBytes.slice(1, selfOut.propositionBytes.size)
  val selfInTree = SELF.propositionBytes.slice(1, SELF.propositionBytes.size)

  val commonPreservationRules =
    selfOut.tokens(0) == SELF.tokens(0) && // NFT preserved
    selfOut.tokens(1)._1 == SELF.tokens(1)._1 && // GORT token id preserved
    selfOutTree == selfInTree && // script preserved
    selfOut.value >= SELF.value // ERG value preserved or increased

  val action = getVar[Byte](1).get

  if (action == 0) {  // top-up:
    sigmaProp(
        commonPreservationRules &&
        selfOut.tokens(1)._2 > SELF.tokens(1)._2 && // GORTs must be added
        selfOut.R4[Int].get == lastHeight && // payout height preserved
        selfOut.R5[SigmaProp].get == SELF.R5[SigmaProp].get // auth preserved
    )
  } else {  // withdrawal
    val newHeight = selfOut.R4[Int].get
    sigmaProp(
        commonPreservationRules &&
        SELF.tokens(1)._2 > selfOut.tokens(1)._2 && // GORTs withdrawn
        SELF.tokens(1)._2 - selfOut.tokens(1)._2 <= newHeight - lastHeight && // <= 1 GORT per block can be released
        newHeight > lastHeight && // payout height increased
        newHeight <= HEIGHT   // can't take rewards from future
        // R5 is not checked here so could be changed
    ) && SELF.R5[SigmaProp].get // signature from proposition stored in R5 is needed to withdraw (and possibly update payout data)
  }
}

{
    // This box: Tracking box
    //
    // TOKENS
    //   tokens(0): Tracking NFT
    //
    // REGISTERS
    //   R4: Int (nominator)
    //   R5: Int (denumerator)
    //   R6: Boolean (isBelow, a flag indicating the type of tracking)
    //   R7: Int (trackingHeight)
    //
    // TRANSACTIONS
    // [1] Update tracker
    //   Input         |  Output        |   Data-Input
    // -----------------------------------------------
    // 0 Tracking box  |  Tracking box  |   Oracle
    // 1               |                |   LP


    // Oracle data:
    // R4 of the oracle contains the rate "nanoErgs per USD" in Long format

    //
    // A "tracker" is like a monitor that triggers an alarm when an event occurs.
    // The alarm continues to "ring" until the tracker resets the alarm, which can only happen after the event has ended.
    // Thus, if the alarm is in a "triggered" state, we can be sure that the event is ongoing (i.e., not yet ended).
    // In our case, the event we are monitoring is the ratio of LP rate and Oracle rate going below (or above) some value.
    // The registers define the ratio to monitor (R4, R5) and whether we are monitoring above or below (R6), along with
    // the height at which the trigger occurred (R7). The value in R7 will be "infinity" if the event has ended.

    // This box is be spent whenever tracker state must change i.e., move from trigger to reset or vice versa
    // This box can only be be spent if the tracker state changes.
    // Someone must spend this box keeping LP as data input.

    val threshold = 3 // error threshold in trigger height, in number of blocks

    val oracleBoxIndex = 0
    val lpBoxIndex = 1
    val selfOutIndex = 0

    val lpNFT = fromBase64("0101010101010101010101010101010101010101010101010101010101010101") // to identify LP box
    val oracleNFT = fromBase64("0202020202020202020202020202020202020202020202020202020202020202") // to identify oracle pool box

    val lpBox = CONTEXT.dataInputs(lpBoxIndex)
    val oracleBox = CONTEXT.dataInputs(oracleBoxIndex)
    val successor = OUTPUTS(selfOutIndex)

    val tokenY = lpBox.tokens(2)  // Dexy tokens

    val validLp = lpBox.tokens(0)._1 == lpNFT

    val validOracleBox = oracleBox.tokens(0)._1 == oracleNFT
    val validSuccessor = successor.tokens == SELF.tokens                      &&
                         successor.propositionBytes == SELF.propositionBytes  &&
                         SELF.value <= successor.value

    // oracle delivers nanoErgs per 1 kg of gold
    // we divide it by 1000000 to get nanoErg per dexy, i.e. 1 mg of gold
    // we assume always > 0 (ref oracle pool contracts) NanoErgs per USD
    val oracleRateXY = oracleBox.R4[Long].get / 1000000L
    val reservesX = lpBox.value
    val reservesY = tokenY._2   // number of Dexy tokens
    val lpRateXY = reservesX / reservesY  // we can assume that reservesY > 0 (since at least one token must exist)

    // Let t = num/denom
    // trackerHeight is the height at which the tracker was "triggered".
    // If the tracker "reset", then trackerHeight will store Int.MaxValue
    //
    // isBelow tells us if the tracking should be tracking "below" or "above" the ratio.
    // Let r be the ratio "oracle pool rate" / "LP rate", where the term "rate" denotes "Ergs per dexy"
    // Now, if "isBelow" is true (i.e. "lower" tracking), then the tracker will be triggered when r goes below t and will be reset once r goes above t

    // there are three tracking boxes as of now:
    // box # | num | denom | height | isBelow
    // ------+-----+-------+--------+--------
    // 1     | 95  | 100   | _      | true     (for extracting to future)
    // 2     | 98  | 100   | _      | true     (for arbitrage mint)
    // 3     | 101 | 100   | _      | false    (for release in future - reverse of extract to future)


    val numIn = SELF.R4[Int].get
    val denomIn = SELF.R5[Int].get
    val isBelowIn = SELF.R6[Boolean].get
    val trackerHeightIn = SELF.R7[Int].get

    val numOut = successor.R4[Int].get
    val denomOut = successor.R5[Int].get
    val isBelowOut = successor.R6[Boolean].get
    val trackerHeightOut = successor.R7[Int].get

    val validTracking = {
        // For a ratio of 95%, set num to 95 and denom to 100, and set isBelow to true
        // Then trackerHeight will be set when oracle pool rate becomes <= 95% of LP rate
        // and it will be reset to Int.MaxValue when that rate becomes > than 95% of LP rate
        //
        // Let oracle pool rate be P and LP rate at earlier point be L0 and currently (via data input) be L1
        // Let N and D denote num and denom respectively. Then we can use the following table to decide correctness
        //
        // EVENT    | isBelow | INPUT       | OUTPUT
        // ---------+---------+-------------+-----------
        // trigger  | true    | L0/P >= N/D | L1/P <  N/D
        // reset    | true    | L0/P <  N/D | L1/P >= N/D (reverse of 1st row)
        // ---------+---------+-------------+------------
        // trigger  | false   | L0/P <= N/D | L1/P >  N/D
        // reset    | false   | L0/P >  N/D | L1/P <= N/D (reverse of 1st row)

        val x = lpRateXY * denomIn
        val y = numIn * oracleRateXY

        val notTriggeredEarlier = trackerHeightIn == $intMax  // Infinity
        val triggeredNow = trackerHeightOut >= HEIGHT - threshold &&
                           trackerHeightOut <= HEIGHT

        val notResetEarlier = trackerHeightIn < $intMax       // Less than Infinity
        val resetNow = trackerHeightOut == $intMax            // Infinity

        val trigger = ((isBelowIn && x < y) || (!isBelowIn && x > y)) && notTriggeredEarlier && triggeredNow
        val reset = ((isBelowIn && x >= y) || (!isBelowIn && x <= y)) && notResetEarlier && resetNow
        val correctAction = trigger || reset

        numOut == numIn          &&
        denomOut == denomIn      &&
        isBelowOut == isBelowIn  &&
        correctAction
    }

    sigmaProp(validSuccessor && validLp && validOracleBox && validTracking)
}

